export const POPULAR_CATALOG_IDS = catalog
  .filter(e => e.popular)
  .map(e => e.id);

export function searchCatalog(query: string, category?: CatalogCategory | "All"): CatalogEntry[] {
  const q = query.toLowerCase().trim();
  return catalog.filter(entry => {
    const matchesSearch = !q ||
      entry.name.toLowerCase().includes(q) ||
      entry.category.toLowerCase().includes(q) ||
      entry.website?.toLowerCase().includes(q);
    const matchesCategory = !category || category === "All" || entry.category === category;
    return matchesSearch && matchesCategory;
  });
}
